82	export const orderSchema = z.object({
83	  planId: z.string().min(1),
84	  osTemplateId: z.string().min(1),
85	  hostname: z
86	    .string()
87	    .min(3)
88	    .max(40)
89	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
90	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
91	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
92	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
93	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
94	  // redemption guards live in orderQuote / placeOrder.
95	  couponCode: z.string().trim().max(32).optional(),
96	});
