98	export type OrderIntent = {
99	  planId: string;
100	  osTemplateId: string;
101	  hostname: string;
102	  nodeId?: string;
103	  addonMalware?: boolean;
104	  addonBackup?: boolean;
105	  addonDocker?: boolean;
106	  termMonths?: number;
107	  dedicatedIp?: boolean;
108	  sshPublicKey?: string;
109	  sshKeyName?: string;
110	  free?: boolean;
111	  /**
112	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
113	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
114	   * post-deploy expansion job is needed. Permanent — never shrinks.
115	   */
116	  extraDiskGB?: number;
117	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
118	  couponCode?: string;
119	  /**
120	   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
121	   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
122	   * metadata, so it stays a tiny string.
123	   */
124	  backupTier?: BackupTier;
125	  /**
126	   * Set by payAndDeploy from the nx_partner_ref cookie (lib/partner.ts) when the
127	   * customer arrived via a partner deep link (?ref=kodely). Round-tripped through
128	   * Stripe metadata like the other optional fields above, then persisted onto the
129	   * created Server row so worker/index.ts knows whether to notify the partner on
130	   * provision success — undefined (never the literal string) for a direct order.
131	   */
132	  partnerSource?: string;
133	};
134	
135	/**
136	 * The price an order was SOLD at: the total, and the promo rate that produced it.
137	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
138	 *
139	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
140	 * path quoted a total, charged the CARD its share of that total at Stripe, and
141	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
142	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
143	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
144	 * so a rotation between "customer clicked Deploy" and "customer came back from
145	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
146	 * out of the wallet with no new consent. With no balance to take it from, the
147	 * payment was captured and no server was created.
148	 *
149	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
150	 * Stripe metadata for exactly this reason; the order path was the one that
151	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
152	 * the customer was shown is not recomputed later, it is carried.
153	 *
154	 * `promoPercent` and `promoName` travel WITH the total because they are not
155	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
156	 * at (every later proration prices against it), and the promo name is the ledger
157	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
158	 * today's 15% would hand every later proration the wrong basis and print a
159	 * discount on the invoice that does not match the money taken.
160	 */
161	export type OrderPrice = {
162	  /**
163	   * The NET (pre-tax) total the customer consented to, in cents. Its meaning is
164	   * unchanged by Finding 1 — every promo/coupon/proration figure is computed against
165	   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
166	   */
167	  chargeCents: number;
168	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
169	  promoPercent: number;
170	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
171	  promoName: string;
172	  /**
173	   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
174	   * confirm route settles the SAME tax-inclusive total the card leg was split from
175	   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
176	   * in which case the charge path recomputes it from the owner's country (0 by
177	   * default), which can only ever undertax, the conservative direction.
178	   */
179	  taxCents?: number;
180	  taxRatePercent?: number;
181	  taxCountry?: string;
182	};
183	
184	/**
185	 * The sold price implied by a quote — the ONE place a quote becomes a price. An
186	 * optional resolved tax context stamps the VAT the card round-trip must settle.
187	 */
188	export function orderPriceOf(
189	  quote: {
190	    chargeCents: number;
191	    promo: { discountPercent: number; name: string };
192	  },
193	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
194	): OrderPrice {
195	  return {
196	    chargeCents: quote.chargeCents,
197	    promoPercent: quote.promo.discountPercent,
198	    promoName: quote.promo.name,
199	    ...(tax
200	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
201	      : {}),
202	  };
203	}
204	
205	/**
206	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
207	 * well-formed: a half-parsed price would be worse than no price at all, because
208	 * the caller's fallback (re-quote) is at least internally consistent.
209	 */
210	export function parseOrderPrice(raw: unknown): OrderPrice | null {
211	  let obj: unknown = raw;
212	  if (typeof raw === "string") {
213	    try {
214	      obj = JSON.parse(raw);
215	    } catch {
216	      return null;
217	    }
218	  }
219	  if (!obj || typeof obj !== "object") return null;
220	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
221	    obj as Record<string, unknown>;
222	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
223	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
224	  if (promoPercent < 0 || promoPercent > 100) return null;
225	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
226	  // malformed tax field) carries none, and the charge path recomputes tax from the
227	  // owner's country — which undertaxes at worst, never overcharges.
228	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
229	  const tr =
230	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
231	      ? taxRatePercent
232	      : 0;
233	  return {
234	    chargeCents,
235	    promoPercent,
236	    promoName: typeof promoName === "string" ? promoName : "",
237	    taxCents: tc,
238	    taxRatePercent: tr,
239	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
240	  };
241	}
