516	/**
517	 * Place an order: validate, charge the wallet (unless a free admin grant),
518	 * create the Server + PROVISION job. Returns the new server id. Does NOT
519	 * redirect. Callers must ensure funds exist (or pass free) — this still
520	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
521	 *
522	 * `sold` overrides the recomputed price with the one the order was actually SOLD
523	 * at — the card-paid path passes the figure stamped on the Checkout session
524	 * BEFORE the card was charged, so the confirm redirect settles the price the
525	 * customer consented to instead of re-pricing against whatever promo is running
526	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
527	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
528	 * quote, which it computed moments ago in the same request. See OrderPrice.
529	 */
530	/**
531	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
532	 * any failure so nothing partial survives. Kept separate from the order tx so a
533	 * wallet order can surface the failure before any money moves, and a card order
534	 * (already paid) can swallow it without stranding the paid provision.
535	 *
536	 * Guards, all enforced here: first-time-only (no prior paid server), the
537	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
538	 * (the two @@unique constraints on CouponRedemption).
539	 */
540	async function claimOrderCoupon(opts: {
541	  couponId: string;
542	  maxRedemptions: number | null;
543	  firstTimeOnly: boolean;
544	  userId: string;
545	  ipHash: string | null;
546	  amountCents: number;
547	}): Promise<void> {
548	  await db.$transaction(async (tx) => {
549	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
550	    // not stand between them and this coupon on a fresh (wallet) order — and its global
551	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
552	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
553	    if (opts.firstTimeOnly) {
554	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
555	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
556	    }
557	    // Atomic conditional increment — the only thing between the last free slot and
558	    // an over-redemption when two orders race for it.
559	    const claim = await tx.coupon.updateMany({
560	      where:
561	        opts.maxRedemptions === null
562	          ? { id: opts.couponId, active: true }
563	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
564	      data: { timesRedeemed: { increment: 1 } },
565	    });
566	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
567	    try {
568	      await tx.couponRedemption.create({
569	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
570	      });
571	    } catch {
572	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
573	      // this person. Throwing rolls back the increment above with it.
574	      throw new OrderError("You’ve already used this code.");
575	    }
576	  });
577	}
