579	/**
580	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
581	 *
582	 * The card leg discounts `cardCents` up front and only settles the redemption
583	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
584	 * paid provision is never stranded. Without this pre-check, a customer who has
585	 * already used a one-per-person code (or isn't first-time) still gets the
586	 * discounted card charge and the swallow hides it. So before we send them to
587	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
588	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
589	 * (a race could still lose the atomic claim at settle time — that path stays
590	 * swallowed by design), but it closes the everyday bypass.
591	 */
592	export async function orderCouponClaimable(opts: {
593	  couponId: string;
594	  firstTimeOnly: boolean;
595	  maxRedemptions: number | null;
596	  userId: string;
597	  ipHash: string | null;
598	}): Promise<{ ok: true } | { ok: false; error: string }> {
599	  if (opts.firstTimeOnly) {
600	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
601	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
602	  }
603	  const byUser = await db.couponRedemption.findUnique({
604	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
605	  });
606	  if (byUser) return { ok: false, error: "You’ve already used this code." };
607	  if (opts.ipHash) {
608	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
609	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
610	  }
611	  if (opts.maxRedemptions !== null) {
612	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
613	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
614	  }
615	  return { ok: true };
616	}
