933	          // later proration prices the plan delta against this number instead of
934	          // whatever promo happens to be running when the customer clicks resize
935	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
936	          // half of a round trip by choosing the date, and pockets the spread.
937	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
938	          // this scalar and the cash collected describe the same transaction.
939	          // A free admin grant recorded as 100: nothing was paid for these months,
940	          // so nothing may ever prorate out of them.
941	          //
942	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
943	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
944	          // may no longer be the promo running now, AND because a wallet order that
945	          // lost the first-month-free claim paid FULL price (0% off): recording 100
946	          // there would let a later downgrade prorate out a discount nobody was
947	          // charged. Recording today's rate against a price collected under a
948	          // different one is exactly the drift this column exists to prevent.
949	          termPromoPercent: effectivePromoPercent,
950	          // The ANNUAL discount rate in force when this term was sold, frozen here so
951	          // every later proration prices against it and an up-then-down round trip nets
952	          // to zero even if the admin retunes `annual_discount_percent` in between
953	          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
954	          // grant never prorates, so its value is inert. `quote.annualPct` is the very
955	          // rate `regularPlanCents`/`chargeCents` above were priced at.
956	          annualDiscountPct: quote.annualPct,
957	          // The plan-portion cash actually collected for this term, net of promo AND
958	          // coupon AND the intro discount, EXCLUDING recurring add-ons — the
959	          // authoritative refund basis (see Server.refundableTermCents).
960	          // `regularPlanCents` is the full term list; subtract the promo credit ONLY if
961	          // the claim held (a lost wallet claim paid full, `soldFull`), always subtract
962	          // the coupon, and always subtract the intro discount (both reduced cash but
963	          // not `termPromoPercent`; the intro discount is baked into `chargeCents`).
964	          // Clamped ≥ 0. A free admin grant collected nothing, so 0.
965	          refundableTermCents: freeRequested
966	            ? 0
967	            : Math.max(
968	                0,
969	                quote.regularPlanCents -
970	                  (soldFull ? 0 : promoCreditCents) -
971	                  quote.couponDiscountCents -
972	                  quote.introDiscountCents,
973	              ),
974	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
975	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
976	          // born at its full size, with no separate expansion job.
977	          extraDiskGB,
978	          wantsDedicatedIp: !!intent.dedicatedIp,
979	          isFree: freeRequested,
980	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
981	        } as Prisma.ServerUncheckedCreateInput,
982	      });
983	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
984	      // Anchor the redemption to the created server so the renewal worker can flip
985	      // `renewed` when this customer bills their second term, and stamp the true
986	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
987	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
988	      return s;
989	    });
990	  } catch (e) {
991	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
992	    throw e;
993	  }
994	
995	  await db.auditLog.create({
996	    data: {
997	      userId: user.id,
998	      action: "server.order",
999	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
1000	    },
1001	  });
1002	  if (!freeRequested) {
1003	    try {
1004	      await maybeRewardReferral(user.id);
1005	    } catch {
1006	      /* non-fatal */
1007	    }
1008	    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
1009	    // over the customer's budget. Best-effort — never fails an order.
1010	    await maybeAlertBudget(user.id);
1011	    // KOL/Agency partner commission: if this customer is attached to a partner,
1012	    // accrue commission on the PAID order invoice now (idempotent; the background
1013	    // sweep would otherwise catch it within minutes). Best-effort by design.
1014	    await accrueRecentCommissionsForCustomer(user.id);
1015	  }
1016	  // Deploy-funnel COMPLETION — the authoritative, server-side bottom of the funnel.
1017	  // This is the ONE place a VPS order is definitively created & paid: both the wallet
1018	  // path (lib/actions.ts payAndDeploy) and the card path (lib/fulfil-checkout.ts, run
1019	  // by the Stripe webhook or the success redirect) reach it, so recording here counts
1020	  // every completed VPS deploy exactly once, with a reliable `userId`. The step index
1021	  // orders it at the tail (after Review/Payment); the completion is a terminal event,
1022	  // not a wizard step, so it drives the completed counts rather than rendering a row.
1023	  // Best-effort AND double-guarded: `recordDeployFunnelComplete` already swallows every
1024	  // failure, and the extra catch guarantees analytics can never disturb the money path.
1025	  try {
1026	    await recordDeployFunnelComplete({ product: "vps", step: "Complete", stepIndex: 8, userId: user.id });
1027	  } catch {
1028	    /* never let funnel bookkeeping affect a completed order */
1029	  }
1030	  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
1031	  // the money has already moved, so a mail failure must NEVER surface as an order
1032	  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
1033	  // path (lib/actions.ts) and the card path (lib/fulfil-checkout.ts) because both go
1034	  // through this one placeOrder. This is the invoice DOCUMENT — deliberately
1035	  // `invoiceNew` (subject "Invoice #… — $… due"), not `receipt`, so it does not
1036	  // collide with the separate "Payment received" wallet/card top-up receipt a card
1037	  // order already gets from lib/stripe.ts. Passing `invoiceId` + the `invoice_new`
1038	  // template makes lib/mailer.ts auto-attach the rendered PDF. `orderInvoice` is null
1039	  // for free admin grants (no invoice created), so those email nothing.
1040	  // Read via the declared union — the value is assigned inside the $transaction
1041	  // callback, which TS control-flow analysis does not track, so a direct read would
1042	  // narrow to `null`.
1043	  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number; description: string } | null;
1044	  if (invForEmail) {
1045	    try {
1046	      const { sendMail, emails } = await import("./mailer");
1047	      const branding = await invoiceBranding();
1048	      const tpl = emails.invoiceNew(
1049	        {
1050	          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
1051	          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
1052	          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
1053	          description: invForEmail.description,
1054	        },
1055	        true, // the itemised PDF is attached (invoiceId passed below)
1056	      );
1057	      await sendMail({
1058	        to: user.email,
1059	        subject: tpl.subject,
1060	        html: tpl.html,
1061	        template: tpl.template,
1062	        invoiceId: invForEmail.id,
1063	        userId: user.id,
1064	        kind: "invoice",
1065	      });
1066	    } catch {
1067	      /* invoice email is best-effort — a placed order must never fail on mail */
1068	    }
1069	  }
1070	  return server.id;
1071	}
