68	/** Extract a GameOrderIntent from a deploy form — shared by the wallet/card wizard
69	 *  action (lib/actions-gameplans.ts) and the PayPal/Coinbase order-creation actions
70	 *  (lib/actions-payment-providers.ts), so both parse the SAME form shape. Pure —
71	 *  lives in this plain module for the same "don't export a non-guarding helper from
72	 *  a Server Actions file" reason `gameOrderGate` above documents. */
73	export function gameIntentFromFormData(formData: FormData): GameOrderIntent {
74	  let config: Record<string, unknown> | null = null;
75	  const rawConfig = formData.get("config");
76	  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
77	    try {
78	      const parsed = JSON.parse(rawConfig);
79	      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
80	    } catch {
81	      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
82	      // fills defaults. It can never widen the charge (game is a flat term price).
83	      config = null;
84	    }
85	  }
86	  return {
87	    gamePlanId: String(formData.get("gamePlanId") ?? ""),
88	    termMonths: Number(formData.get("termMonths") ?? 1),
89	    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
90	    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
91	    variant: String(formData.get("variant") ?? "").trim() || undefined,
92	    config,
93	  };
94	}
