96	/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
97	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
98	
99	/** Short random suffix so auto-generated hostnames don't collide. */
100	export function randSuffix(n = 6): string {
101	  return Math.random().toString(36).slice(2, 2 + n);
102	}
103	
104	/**
105	 * The customer's full game-order intent — the tier, the billing term and the
106	 * per-game setup captured by the wizard. `config` holds the raw gameplay values
107	 * (validated against the family schema in `gameOrderQuote`); `variant` is the
108	 * server type/loader.
109	 */
110	export type GameOrderIntent = {
111	  gamePlanId: string;
112	  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
113	  termMonths: number;
114	  /** Optional customer-facing nickname → Server.label. */
115	  serverName?: string;
116	  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
117	  hostname?: string;
118	  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
119	  variant?: string;
120	  /** Raw gameplay settings; validated + coerced against the family schema. */
121	  config?: Record<string, unknown> | null;
122	};
123	
124	/**
125	 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
126	 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
127	 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
128	 * OrderPrice, which must also carry promo + VAT).
129	 */
130	export type GameOrderPrice = { chargeCents: number };
131	
132	/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
133	export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
134	  let obj: unknown = raw;
135	  if (typeof raw === "string") {
136	    try {
137	      obj = JSON.parse(raw);
138	    } catch {
139	      return null;
140	    }
141	  }
142	  if (!obj || typeof obj !== "object") return null;
143	  const { chargeCents } = obj as Record<string, unknown>;
144	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
145	  return { chargeCents };
146	}
147	
148	export type GameOrderQuote = {
149	  gamePlanId: string;
150	  gameFamily: string;
151	  planName: string;
152	  basePlanId: string;
153	  osTemplateId: string;
154	  /** Normalised term (1 or 12). */
155	  term: number;
156	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
157	  annualPct: number;
158	  /** DB-fed per-month base (priceCents / termMonths). */
159	  monthlyCents: number;
160	  /** The net charge for the whole term — displayed === charged === renewed. */
161	  chargeCents: number;
162	  hostname: string;
163	  label: string | null;
164	  variant: string;
165	  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
166	  values: Record<string, string | number | boolean>;
167	};
168	
169	/**
170	 * Validate + price a game order without placing it. Throws GameOrderError on any
171	 * problem. Pure of side effects beyond reads. The price is the whole truth about
172	 * what this order costs; the caller (wallet split, review step, checkout stamp)
173	 * quotes from THIS so what the customer sees is what settles.
174	 */
175	export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
176	  const term = normalizeProductTerm(intent.termMonths);
177	
178	  const gp = await db.gamePlan.findUnique({
179	    where: { id: intent.gamePlanId },
180	    include: { basePlan: true },
181	  });
182	  if (!gp || !gp.active) throw new GameOrderError("That game plan isn't available.");
183	  if (!gp.basePlan?.active) throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
184	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
185	    throw new GameOrderError("Unknown game family.");
186	  }
187	
188	  // Resolve the game image: the tier's own OsTemplate, else any active image for
189	  // this family. A game server can't provision without an image.
190	  let osTemplateId = gp.osTemplateId;
191	  if (osTemplateId) {
192	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
193	    if (!os?.active) osTemplateId = null;
194	  }
195	  if (!osTemplateId) {
196	    const os = await db.osTemplate.findFirst({
197	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
198	      orderBy: { sortOrder: "asc" },
199	    });
200	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
201	    osTemplateId = os.id;
202	  }
203	
204	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
205	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
206	  let hostname = rawHost;
207	  if (hostname === "") {
208	    hostname = `${gp.gameFamily}-${randSuffix()}`;
209	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
210	    throw new GameOrderError(
211	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
212	    );
213	  }
214	
215	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
216	
217	  // Per-game setup: variant + gameplay settings, validated against the family
218	  // schema. Families without a customization schema (e.g. Terraria) carry no
219	  // variant and no gameplay values — the wizard shows only identity fields for them.
220	  const schema = schemaFor(gp.gameFamily);
221	  let variant = "";
222	  let values: Record<string, string | number | boolean> = {};
223	  if (schema) {
224	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
225	    if (!isValidVariant(gp.gameFamily, variant)) {
226	      throw new GameOrderError("Choose a valid server type for this game.");
227	    }
228	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
229	    if (!res.ok) throw new GameOrderError(res.error);
230	    values = res.values;
231	  }
232	
233	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
234	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
235	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
236	  const annualPct = await annualDiscountPct();
237	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
238	  const chargeCents = termPriceCents(monthlyCents, term, annualPct);
239	
240	  return {
241	    gamePlanId: gp.id,
242	    gameFamily: gp.gameFamily,
243	    planName: gp.name,
244	    basePlanId: gp.basePlanId,
245	    osTemplateId,
246	    term,
247	    annualPct,
248	    monthlyCents,
249	    chargeCents,
250	    hostname,
251	    label,
252	    variant,
253	    values,
254	  };
255	}
