257	/**
258	 * Place a game order: re-validate + price, capacity-check, then atomically debit
259	 * the wallet and create the Server (sized by the tier's base VPS plan, running the
260	 * game image, with the customer's variant + gameplay settings) plus a PROVISION
261	 * job. Returns the new server id. Does NOT redirect.
262	 *
263	 * `sold` (card path) overrides the recomputed price with the one the order was
264	 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
265	 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
266	 * the customer consented to instead of re-pricing against a rate that changed in
267	 * between. The wallet path omits it and pays the fresh quote it computed moments
268	 * ago. This mirrors `sold` in lib/order.ts placeOrder.
269	 *
270	 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
271	 * path is gated by the balance check in the action). This still enforces the
272	 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
273	 */
274	export async function placeGameOrder(
275	  user: User,
276	  intent: GameOrderIntent,
277	  sold?: GameOrderPrice | null,
278	): Promise<string> {
279	  const quote = await gameOrderQuote(intent);
280	
281	  // Bill off the SOLD price when present (never re-priced after the card cleared),
282	  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
283	  // truth about what this order costs.
284	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
285	
286	  // Oversell guard — the VPS order path enforces this; game orders must too, or a
287	  // game server could commit host RAM past capacity.
288	  const capacity = await capacityCheck(quote.basePlanId);
289	  if (!capacity.ok) {
290	    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
291	  }
292	
293	  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
294	  // path the wallet was credited the card leg first, so this holds.
295	  if (user.balanceCents < chargeCents) {
296	    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
297	  }
298	
299	  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
300	  const termLabel =
301	    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;
302	
303	  let server;
304	  try {
305	    server = await db.$transaction(async (tx) => {
306	      await debitWallet(tx, user.id, chargeCents);
307	      await tx.walletTransaction.create({
308	        data: {
309	          userId: user.id,
310	          amountCents: -chargeCents,
311	          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
312	        },
313	      });
314	      const s = await tx.server.create({
315	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
316	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
317	        data: {
318	          name: quote.hostname,
319	          hostname: quote.hostname,
320	          label: quote.label,
321	          userId: user.id,
322	          planId: quote.basePlanId,
323	          gamePlanId: quote.gamePlanId,
324	          osTemplateId: quote.osTemplateId,
325	          // The customer's per-game setup, applied at the point of sale — the worker
326	          // renders these into the game's own config at provision (worker/game-config).
327	          gameVariant: quote.variant || null,
328	          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
329	          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
330	          // game branch renews monthlyCents × termMonths × (1 − annual).
331	          termMonths: quote.term,
332	          // No seasonal promo on game — this term was sold at 0% off, so any future
333	          // proration prices against full price.
334	          termPromoPercent: 0,
335	          // The annual rate frozen at sale, so the renewal bills the SAME price the
336	          // order charged even if the admin retunes annual_discount_percent later.
337	          annualDiscountPct: quote.annualPct,
338	          wantsDedicatedIp: false,
339	          expiresAt: addMonths(new Date(), quote.term),
340	        } as Prisma.ServerUncheckedCreateInput,
341	      });
342	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
343	      return s;
344	    });
345	  } catch (e) {
346	    if (e instanceof InsufficientBalanceError) {
347	      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
348	    }
349	    throw e;
350	  }
351	
352	  await db.auditLog.create({
353	    data: {
354	      userId: user.id,
355	      action: "gameserver.order",
356	      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
357	    },
358	  });
359	  // Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
360	  // place a game order is created & paid, reached by BOTH the wallet path
361	  // (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts webhook /
362	  // redirect), so every completed game deploy is counted once with a reliable userId.
363	  // Terminal event (drives the completed counts, not a wizard-step row); best-effort
364	  // and double-guarded so it can never disturb the money path.
365	  try {
