"use client";

import { useActionState, useEffect, useState } from "react";
import Link from "next/link";
import { login, register } from "@/lib/actions";

/**
 * The three rules `register()` in lib/actions.ts ACTUALLY enforces, restated
 * here so the checklist and the server agree.
 *
 * They used to disagree in both directions: the list demanded "Upper &
 * lowercase" and "A symbol" — neither of which the server checks — and never
 * mentioned the digit rule that it does. `PASSWORD!` therefore scored "Good"
 * and was rejected, while `abcdefg1` was accepted with two ticks missing. A
 * checklist that grades against rules nobody enforces is worse than no
 * checklist: it teaches the customer that the ticks are noise.
 *
 * If the regexes in `register()` change, change these with them.
 */
const REQUIRED_RULES = [
  { test: (v: string) => v.length >= 8, label: "8+ characters" },
  { test: (v: string) => /[a-zA-Z]/.test(v), label: "A letter" },
  { test: (v: string) => /[0-9]/.test(v), label: "A number" },
];

/** Genuinely optional — these make a password stronger but never reject it. */
const BONUS_RULES = [
  { test: (v: string) => /[a-z]/.test(v) && /[A-Z]/.test(v), label: "Upper & lowercase" },
  { test: (v: string) => /[^A-Za-z0-9]/.test(v), label: "A symbol" },
];

function PasswordField({
  id = "password",
  label = "Password",
  autoComplete = "new-password",
  requireStrong = true,
}: {
  id?: string;
  label?: string;
  autoComplete?: string;
  requireStrong?: boolean;
}) {
  const [val, setVal] = useState("");
  const [show, setShow] = useState(false);
  const required = REQUIRED_RULES.map((r) => ({ ok: r.test(val), label: r.label }));
  const bonus = BONUS_RULES.map((r) => ({ ok: r.test(val), label: r.label }));
  const score = [...required, ...bonus].filter((c) => c.ok).length;
  const strengthLabel = ["Too weak", "Too weak", "Weak", "Fair", "Good", "Strong"][score] ?? "Too weak";
  const barColor =
    ["bg-red-500", "bg-red-500", "bg-red-500", "bg-amber-500", "bg-yellow-400", "bg-emerald-500"][score] ??
    "bg-red-500";
  const total = required.length + bonus.length;
  return (
    <div>
      <label className="label" htmlFor={id}>{label}</label>
      <div className="relative">
        <input
          id={id}
          className="input pr-11"
          name="password"
          type={show ? "text" : "password"}
          required
          minLength={8}
          autoComplete={autoComplete}
          value={val}
          onChange={(e) => setVal(e.target.value)}
        />
        <button
          type="button"
          onClick={() => setShow((s) => !s)}
          aria-label={show ? "Hide password" : "Show password"}
          className="absolute right-2 top-1/2 -translate-y-1/2 rounded-md p-1.5 text-slate-400 transition-colors hover:text-slate-200"
        >
          {show ? (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M9.9 4.24A9.1 9.1 0 0 1 12 4c7 0 10 8 10 8a18 18 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
              <path d="M1 1l22 22M6.61 6.61A18 18 0 0 0 2 12s3 8 10 8a9 9 0 0 0 5.39-1.61" />
            </svg>
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M2 12s3-8 10-8 10 8 10 8-3 8-10 8-10-8-10-8Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          )}
        </button>
      </div>
      {requireStrong && val.length > 0 && (
        <div className="mt-2">
          <div className="flex items-center gap-2">
            <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-white/10">

const [email, setEmail] = useState("");
const [code, setCode] = useState("");
// `useActionState` hands back a NEW state object on every completed submit, so
// this runs once per attempt. Still on the 2FA step and carrying an error =>
// the code we just sent was empty or wrong; either way the box should start
// clean for the next 30-second window. A no-op on the first challenge.
useEffect(() => {
  if (state?.needs2fa && state?.error) setCode("");
}, [state]);
return (
  <div className="space-y-4">
    {/* An error bounced back from the Google OAuth routes (see app/login/page.tsx). */}
    <ErrorBox error={googleError} />
    {googleEnabled ? <GoogleButton next={next} /> : null}
    <form action={action} className="space-y-4">
      {/*
      Where the visitor was heading. Re-validated by `safeNext` in
      lib/actions.ts before any redirect — an unvalidated `next` on a login
      form is an open redirect and therefore a phishing primitive, so this
      value is carried, never trusted.
    */}
      {next ? <input type="hidden" name="next" value={next} /> : null}
      <ErrorBox error={state?.error} />
    <div>
      <label className="label" htmlFor="login-email">Email</label>
      <input
        id="login-email"
        className="input"
        name="email"
        type="email"
        required
        autoComplete="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
    </div>
    <PasswordField id="login-password" label="Password" autoComplete="current-password" requireStrong={false} />
    {state?.needs2fa && (
      <div>
        <label className="label" htmlFor="login-2fa-code">2FA code</label>
        {/* Controlled like the rest, so nothing here depends on React's reset
            behaviour. A rejected code is cleared DELIBERATELY below (a TOTP
            code is single-use and time-boxed, so keeping a stale one in the
            box only makes the customer clear it themselves) — the point is
            that the clearing is a decision, not a side effect. */}
        <input
          id="login-2fa-code"
          className="input tracking-[0.3em]"
          name="code"
          inputMode="numeric"
          autoComplete="one-time-code"
          placeholder="123456"
          autoFocus
          value={code}
          onChange={(e) => setCode(e.target.value)}
        />
        <p className="mt-1 text-xs text-slate-500">Enter the 6-digit code from your authenticator app, or a backup code.</p>
      </div>
    )}
    <button className="btn-primary w-full" disabled={pending}>
      {pending ? "Signing in…" : state?.needs2fa ? "Verify & sign in" : "Sign in"}
    </button>
    <div className="flex items-center justify-between text-sm text-slate-400">
      <Link href={next ? `/register?next=${encodeURIComponent(next)}` : "/register"} className="text-brand-300 hover:underline">
        Create account
      </Link>

